"""Build the illustrated guide from synthetic screenshots of the published app."""
import argparse
from pathlib import Path
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.styles import ParagraphStyle
from reportlab.platypus import Paragraph
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.utils import ImageReader

parser = argparse.ArgumentParser()
parser.add_argument('--screenshots', required=True)
parser.add_argument('--output', default='public/guide/eventflow-guide.pdf')
parser.add_argument('--font-dir', default='C:/Windows/Fonts')
args = parser.parse_args()
fonts = Path(args.font_dir)
pdfmetrics.registerFont(TTFont('Guide', str(fonts / 'arial.ttf')))
pdfmetrics.registerFont(TTFont('GuideBold', str(fonts / 'arialbd.ttf')))
pdfmetrics.registerFontFamily('Guide', normal='Guide', bold='GuideBold', italic='Guide', boldItalic='GuideBold')
body = ParagraphStyle('Body', fontName='Guide', fontSize=10.6, leading=15.2, textColor=colors.HexColor('#293c58'), spaceAfter=8)
caption = ParagraphStyle('Caption', parent=body, fontSize=8, leading=11, textColor=colors.HexColor('#667e9c'))
note = ParagraphStyle('Note', parent=body, fontSize=10.1, leading=14)
