output = Path(args.output)
output.parent.mkdir(parents=True, exist_ok=True)
pdf = canvas.Canvas(str(output), pagesize=A4)
pdf.setTitle('EventFlow - инструкция со скриншотами')
pdf.setAuthor('EventFlow')
width, height = A4
margin = 40
usable = width - margin * 2

def draw_paragraph(text, y, style=body, x=margin, box_width=usable):
    paragraph = Paragraph(text, style)
    _, size = paragraph.wrap(box_width, height)
    paragraph.drawOn(pdf, x, y - size)
    return y - size - 8

for number, page in enumerate(pages, 1):
    pdf.setFillColor(colors.HexColor('#126bd0'))
    pdf.setFont('GuideBold', 9)
    pdf.drawString(margin, height - 35, f'EVENTFLOW  /  РУКОВОДСТВО  /  {number:02d}')
    pdf.setFillColor(colors.HexColor('#112848'))
    pdf.setFont('GuideBold', 21)
    pdf.drawString(margin, height - 67, page['title'])
    pdf.setStrokeColor(colors.HexColor('#dce7f5'))
    pdf.line(margin, height - 82, width - margin, height - 82)
    y = height - 96
    image_path = Path(args.screenshots) / page['image']
    if not image_path.exists():
        raise FileNotFoundError(image_path)
    image = ImageReader(str(image_path))
    iw, ih = image.getSize()
    scale = min(usable / iw, 277 / ih)
    drawn_width, drawn_height = iw * scale, ih * scale
    pdf.drawImage(image, margin + (usable - drawn_width) / 2, y - drawn_height, width=drawn_width, height=drawn_height, mask='auto')
    y -= drawn_height + 9
    y = draw_paragraph(page['caption'], y, caption)
    y -= 3
    for step in page['steps']:
        y = draw_paragraph(step, y)
    callout = Paragraph(page['note'], note)
    _, size = callout.wrap(usable - 24, height)
    if y - size - 24 < 46:
        raise RuntimeError(f'Page {number} overflows: y={y}, note={size}')
    pdf.setFillColor(colors.HexColor('#eff7ff'))
    pdf.roundRect(margin, y - size - 18, usable, size + 18, 7, fill=1, stroke=0)
    callout.drawOn(pdf, margin + 12, y - size - 8)
    pdf.setFillColor(colors.HexColor('#7c8ba0'))
    pdf.setFont('Guide', 8)
    pdf.drawString(margin, 24, '20.11.2026  |  Скриншоты опубликованной версии на учебных данных')
    pdf.drawRightString(width - margin, 24, f'{number} / {len(pages)}')
    pdf.showPage()
pdf.save()
print(f'{output.resolve()} - {len(pages)} pages')
